CREATE FUNCTION public.atializavagasmenos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin

UPDATE atividade

set vagasdisponiveis = GREATEST(0,vagasdisponiveis - 1), qtdeinscritos=qtdeinscritos +1

Where id = NEW.id_atividade ;

return NEW;

END;

$$;


