CREATE FUNCTION public.atualizavagasmais() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin

UPDATE atividade

set vagasdisponiveis = vagasdisponiveis + 1,qtdeinscritos=qtdeinscritos - 1 

