--
-- Name: profiledadosupdate(); Type: FUNCTION; Schema: public; Owner: computacaoifg
--

CREATE FUNCTION public.profiledadosupdate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$declare 

  mail varchar(70);

begin

select email into mail from users 

where id=NEW.user_id;

update "DadosPessoais"

set nome=NEW.firstname , cpf= NEW.cpf, email=mail

where cpf=NEW.cpf;

return NEW;

END;$$;


