--
-- Name: profilestodados(); Type: FUNCTION; Schema: public; Owner: computacaoifg
--

CREATE FUNCTION public.profilestodados() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

declare 

  mail varchar(256);

begin

select email into mail from users 

where id=NEW.user_id;


select NEW.cpf,NEW.firstname,mail

where not exists ( select cpf from "DadosPessoais"  where cpf=NEW.cpf );

--Se já existir um usuário, atualizamos os dados. Existe a possibilidade da inscrição em um evento com o CPF.

update "DadosPessoais"

set nome=NEW.firstname , cpf= NEW.cpf, email=mail

where cpf=NEW.cpf;

return NEW;

END;$$;


