-- Name: user_data; Type: VIEW; Schema: public; Owner: computacaoifg
--

CREATE VIEW public.user_data AS
 SELECT profiles.user_id,
    profiles.firstname,
    users.email,
    users.password,
    'gci'::text AS surname,
    profiles.cpf
   FROM (public.users
     LEFT JOIN public.profiles ON ((profiles.user_id = users.id)))
  WHERE (users.status = 1);


